CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle used in mentions and in the member avatar tooltip.
	"username" VARCHAR(60) NOT NULL UNIQUE,
	-- Login identity and the address notifications go to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown on avatars and activity entries.
	"full_name" VARCHAR(160) NOT NULL,
	-- Profile image URL.
	"avatar_url" VARCHAR(500),
	-- IANA zone. Due-date reminders fire relative to this, which is why a due date is an instant and the reminder is not.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person who can be a board member. Never deleted outright, because every activity entry and card assignment refers back here.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle used in mentions and in the member avatar tooltip.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address notifications go to.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name shown on avatars and activity entries.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile image URL.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA zone. Due-date reminders fire relative to this, which is why a due date is an instant and the reminder is not.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "boards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Board title.
	"name" VARCHAR(200) NOT NULL,
	-- Board description shown in the sidebar.
	"description" TEXT,
	-- Creator, who cannot be removed from the board without a transfer. Null only after a hard account deletion.
	"owner_id" BIGINT,
	-- private | workspace | public. A public board is readable without authentication, which is why it is a board property and not a per-member one.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'private',
	-- Colour name or photo id. Cosmetic, but it is how people recognise a board in a list of thirty.
	"background" VARCHAR(120) NOT NULL DEFAULT 'blue',
	-- Template boards are excluded from the normal board list and are copied rather than opened.
	"is_template" BOOLEAN NOT NULL DEFAULT false,
	-- Template this board was copied from. Kept so a template author can see adoption, and so a board can be re-synced by hand against an updated template.
	"template_source_board_id" BIGINT,
	-- Board-level archive. Closed boards are hidden and read-only but never cascade-deleted, because reopening one has to restore every card exactly as it was.
	"closed_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "boards" IS 'The top-level container and the permission boundary. Everything below it — lists, labels, power-ups, activity — is scoped to a board, which is what makes copying a board a self-contained operation.';
COMMENT ON COLUMN "boards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "boards"."name" IS 'Board title.';
COMMENT ON COLUMN "boards"."description" IS 'Board description shown in the sidebar.';
COMMENT ON COLUMN "boards"."owner_id" IS 'Creator, who cannot be removed from the board without a transfer. Null only after a hard account deletion.';
COMMENT ON COLUMN "boards"."visibility" IS 'private | workspace | public. A public board is readable without authentication, which is why it is a board property and not a per-member one.';
COMMENT ON COLUMN "boards"."background" IS 'Colour name or photo id. Cosmetic, but it is how people recognise a board in a list of thirty.';
COMMENT ON COLUMN "boards"."is_template" IS 'Template boards are excluded from the normal board list and are copied rather than opened.';
COMMENT ON COLUMN "boards"."template_source_board_id" IS 'Template this board was copied from. Kept so a template author can see adoption, and so a board can be re-synced by hand against an updated template.';
COMMENT ON COLUMN "boards"."closed_at" IS 'Board-level archive. Closed boards are hidden and read-only but never cascade-deleted, because reopening one has to restore every card exactly as it was.';
COMMENT ON COLUMN "boards"."created_at" IS 'Creation time.';

CREATE INDEX "idx_boards_owner_open"
ON "boards" ("owner_id", "closed_at");

CREATE TABLE IF NOT EXISTS "board_members" (
	-- Board joined. Half of the composite primary key.
	"board_id" BIGINT,
	-- Member. The other half of the key.
	"user_id" BIGINT,
	-- admin | normal | observer. An observer can comment but cannot move cards, which is the distinction that makes sharing a board with a client safe.
	"role" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- Per-member favourite. It belongs here and not on the board because starring is one persons opinion, not a property of the board.
	"starred" BOOLEAN NOT NULL DEFAULT false,
	-- When the member was added.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("board_id", "user_id")
);

COMMENT ON TABLE "board_members" IS 'Membership and per-board role. The composite key makes duplicate membership impossible and the reverse index renders the board switcher, starred boards first.';
COMMENT ON COLUMN "board_members"."board_id" IS 'Board joined. Half of the composite primary key.';
COMMENT ON COLUMN "board_members"."user_id" IS 'Member. The other half of the key.';
COMMENT ON COLUMN "board_members"."role" IS 'admin | normal | observer. An observer can comment but cannot move cards, which is the distinction that makes sharing a board with a client safe.';
COMMENT ON COLUMN "board_members"."starred" IS 'Per-member favourite. It belongs here and not on the board because starring is one persons opinion, not a property of the board.';
COMMENT ON COLUMN "board_members"."joined_at" IS 'When the member was added.';

CREATE INDEX "idx_board_members_user_starred"
ON "board_members" ("user_id", "starred");

CREATE TABLE IF NOT EXISTS "lists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning board.
	"board_id" BIGINT NOT NULL,
	-- Column heading such as Backlog or Done. Free text rather than a fixed workflow vocabulary, because the columns are the workflow in a board-first tool.
	"name" VARCHAR(200) NOT NULL,
	-- Left-to-right order on the board. Fractional for the same reason card positions are: moving a column rewrites one row.
	"position" NUMERIC(30,15) NOT NULL,
	-- Soft cap on cards in this list. Null for no limit. The app warns rather than blocks, so the limit is advice the database does not enforce.
	"wip_limit" SMALLINT,
	-- Whether the acting member watches everything in this list. Denormalised per board in practice; here it is the list-level default.
	"subscribed" BOOLEAN NOT NULL DEFAULT false,
	-- Archive timestamp. Archiving a list hides it and its cards without moving them, so restoring the list brings the cards back in their original order.
	"archived_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lists" IS 'A column. In a board-first tool the list is the status: there is no separate status column on a card, because a card being in Done is the only fact that means done.';
COMMENT ON COLUMN "lists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lists"."board_id" IS 'Owning board.';
COMMENT ON COLUMN "lists"."name" IS 'Column heading such as Backlog or Done. Free text rather than a fixed workflow vocabulary, because the columns are the workflow in a board-first tool.';
COMMENT ON COLUMN "lists"."position" IS 'Left-to-right order on the board. Fractional for the same reason card positions are: moving a column rewrites one row.';
COMMENT ON COLUMN "lists"."wip_limit" IS 'Soft cap on cards in this list. Null for no limit. The app warns rather than blocks, so the limit is advice the database does not enforce.';
COMMENT ON COLUMN "lists"."subscribed" IS 'Whether the acting member watches everything in this list. Denormalised per board in practice; here it is the list-level default.';
COMMENT ON COLUMN "lists"."archived_at" IS 'Archive timestamp. Archiving a list hides it and its cards without moving them, so restoring the list brings the cards back in their original order.';
COMMENT ON COLUMN "lists"."created_at" IS 'Creation time.';

CREATE INDEX "idx_lists_board_order"
ON "lists" ("board_id", "archived_at", "position");

CREATE TABLE IF NOT EXISTS "cards" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning board, denormalised from the list so board-wide queries and permission checks never join through lists.
	"board_id" BIGINT NOT NULL,
	-- Column the card currently sits in. Moving a card is an update to this plus position, and it is the only record of the cards status.
	"list_id" BIGINT NOT NULL,
	-- Short URL slug. Unique registry-wide and stable across moves, so a link pasted into chat survives the card being dragged to another list or board.
	"short_link" CHAR(8) NOT NULL UNIQUE,
	-- Card title, the only field visible on the board face.
	"name" VARCHAR(500) NOT NULL,
	-- Markdown body, loaded only when the card is opened.
	"description" TEXT,
	-- Vertical order within the list. Dropping a card between two others averages their positions, so a drag writes one row rather than renumbering the column.
	"position" NUMERIC(30,15) NOT NULL,
	-- Deadline as an instant. Null for a card with no deadline, which is most of them.
	"due_at" TIMESTAMPTZ,
	-- Start of the cards window, used by calendar and timeline views. Meaningless without due_at in the UI, though the database allows either alone.
	"start_at" TIMESTAMPTZ,
	-- Whether the due date was met, kept separate from the list because a card can be done on time and still sit in review.
	"due_complete" BOOLEAN NOT NULL DEFAULT false,
	-- Cover configuration: a colour, an attachment id to render full bleed, and the size. JSON because it is read and written whole and never queried on.
	"cover" JSONB,
	-- Maintained count of watchers, so the card face can show the eye icon without a second query.
	"subscribed_count" INTEGER NOT NULL DEFAULT 0,
	-- Archive timestamp. An archived card keeps its list and position, which is what lets an undo put it back where it was rather than at the bottom.
	"archived_at" TIMESTAMPTZ,
	-- Who created it.
	"created_by_id" BIGINT,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last change to the card or anything hanging off it, which the recently-active filter sorts on.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cards" IS 'The unit of work. It has no status column on purpose: in a board-first model the list a card sits in is its status, and adding a second source of truth is how a board and a report start disagreeing.';
COMMENT ON COLUMN "cards"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cards"."board_id" IS 'Owning board, denormalised from the list so board-wide queries and permission checks never join through lists.';
COMMENT ON COLUMN "cards"."list_id" IS 'Column the card currently sits in. Moving a card is an update to this plus position, and it is the only record of the cards status.';
COMMENT ON COLUMN "cards"."short_link" IS 'Short URL slug. Unique registry-wide and stable across moves, so a link pasted into chat survives the card being dragged to another list or board.';
COMMENT ON COLUMN "cards"."name" IS 'Card title, the only field visible on the board face.';
COMMENT ON COLUMN "cards"."description" IS 'Markdown body, loaded only when the card is opened.';
COMMENT ON COLUMN "cards"."position" IS 'Vertical order within the list. Dropping a card between two others averages their positions, so a drag writes one row rather than renumbering the column.';
COMMENT ON COLUMN "cards"."due_at" IS 'Deadline as an instant. Null for a card with no deadline, which is most of them.';
COMMENT ON COLUMN "cards"."start_at" IS 'Start of the cards window, used by calendar and timeline views. Meaningless without due_at in the UI, though the database allows either alone.';
COMMENT ON COLUMN "cards"."due_complete" IS 'Whether the due date was met, kept separate from the list because a card can be done on time and still sit in review.';
COMMENT ON COLUMN "cards"."cover" IS 'Cover configuration: a colour, an attachment id to render full bleed, and the size. JSON because it is read and written whole and never queried on.';
COMMENT ON COLUMN "cards"."subscribed_count" IS 'Maintained count of watchers, so the card face can show the eye icon without a second query.';
COMMENT ON COLUMN "cards"."archived_at" IS 'Archive timestamp. An archived card keeps its list and position, which is what lets an undo put it back where it was rather than at the bottom.';
COMMENT ON COLUMN "cards"."created_by_id" IS 'Who created it.';
COMMENT ON COLUMN "cards"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "cards"."updated_at" IS 'Last change to the card or anything hanging off it, which the recently-active filter sorts on.';

CREATE INDEX "idx_cards_list_order"
ON "cards" ("list_id", "archived_at", "position");
CREATE INDEX "idx_cards_board_due"
ON "cards" ("board_id", "due_at");

CREATE TABLE IF NOT EXISTS "labels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning board. Labels are per board so two teams can both have an urgent without agreeing on a colour.
	"board_id" BIGINT NOT NULL,
	-- Label text. Null is normal and intentional: a colour-only label is the default, and people name them later if at all.
	"name" VARCHAR(120),
	-- Named colour from a fixed palette rather than a hex value, because the palette is also used for the colour-blind friendly mode.
	"color" VARCHAR(20) NOT NULL DEFAULT 'green',
	-- Order in the label picker.
	"position" NUMERIC(30,15) NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "labels" IS 'Board-scoped tagging. Copied along with a board when a template is instantiated, which is why labels belong to the board rather than to a workspace.';
COMMENT ON COLUMN "labels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "labels"."board_id" IS 'Owning board. Labels are per board so two teams can both have an urgent without agreeing on a colour.';
COMMENT ON COLUMN "labels"."name" IS 'Label text. Null is normal and intentional: a colour-only label is the default, and people name them later if at all.';
COMMENT ON COLUMN "labels"."color" IS 'Named colour from a fixed palette rather than a hex value, because the palette is also used for the colour-blind friendly mode.';
COMMENT ON COLUMN "labels"."position" IS 'Order in the label picker.';

CREATE INDEX "idx_labels_board_order"
ON "labels" ("board_id", "position");

CREATE TABLE IF NOT EXISTS "card_labels" (
	-- Card labelled. Half of the composite primary key.
	"card_id" BIGINT,
	-- Label applied. The other half of the key.
	"label_id" BIGINT,
	-- When it was applied, used by the activity feed.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("card_id", "label_id")
);

COMMENT ON TABLE "card_labels" IS 'Many-to-many join with nothing to say beyond existence, so the pair is the primary key and the reverse index answers filter the board by this label.';
COMMENT ON COLUMN "card_labels"."card_id" IS 'Card labelled. Half of the composite primary key.';
COMMENT ON COLUMN "card_labels"."label_id" IS 'Label applied. The other half of the key.';
COMMENT ON COLUMN "card_labels"."added_at" IS 'When it was applied, used by the activity feed.';

CREATE INDEX "idx_card_labels_label"
ON "card_labels" ("label_id");

CREATE TABLE IF NOT EXISTS "checklists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning card.
	"card_id" BIGINT NOT NULL,
	-- Heading, which matters once a card carries several checklists such as Design and QA.
	"name" VARCHAR(200) NOT NULL DEFAULT 'Checklist',
	-- Order of checklists within the card.
	"position" NUMERIC(30,15) NOT NULL,
	-- Checklist this one was copied from, which is how a checklist template on a board is reused. Null for one written from scratch.
	"source_checklist_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "checklists" IS 'A named group of check items. Separate from the card because the useful unit is the group: people copy a whole checklist between cards far more often than a single item.';
COMMENT ON COLUMN "checklists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "checklists"."card_id" IS 'Owning card.';
COMMENT ON COLUMN "checklists"."name" IS 'Heading, which matters once a card carries several checklists such as Design and QA.';
COMMENT ON COLUMN "checklists"."position" IS 'Order of checklists within the card.';
COMMENT ON COLUMN "checklists"."source_checklist_id" IS 'Checklist this one was copied from, which is how a checklist template on a board is reused. Null for one written from scratch.';

CREATE INDEX "idx_checklists_card_order"
ON "checklists" ("card_id", "position");

CREATE TABLE IF NOT EXISTS "check_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning checklist.
	"checklist_id" BIGINT NOT NULL,
	-- Item text.
	"name" VARCHAR(500) NOT NULL,
	-- Order within the checklist.
	"position" NUMERIC(30,15) NOT NULL,
	-- When it was ticked. A timestamp rather than a boolean, so the activity feed and cycle-time reporting get the moment for free.
	"checked_at" TIMESTAMPTZ,
	-- Who ticked it. Null while unchecked, and the reason a tick is attributable at all.
	"checked_by_id" BIGINT,
	-- Per-item deadline, independent of the cards own due date.
	"due_at" TIMESTAMPTZ,
	-- Member responsible for this item. Null is the normal case; it exists so a checklist can act as a lightweight split of work without creating five cards.
	"assignee_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "check_items" IS 'One tickable line. Storing checked_at and checked_by instead of a boolean costs nothing and turns every tick into an auditable event.';
COMMENT ON COLUMN "check_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "check_items"."checklist_id" IS 'Owning checklist.';
COMMENT ON COLUMN "check_items"."name" IS 'Item text.';
COMMENT ON COLUMN "check_items"."position" IS 'Order within the checklist.';
COMMENT ON COLUMN "check_items"."checked_at" IS 'When it was ticked. A timestamp rather than a boolean, so the activity feed and cycle-time reporting get the moment for free.';
COMMENT ON COLUMN "check_items"."checked_by_id" IS 'Who ticked it. Null while unchecked, and the reason a tick is attributable at all.';
COMMENT ON COLUMN "check_items"."due_at" IS 'Per-item deadline, independent of the cards own due date.';
COMMENT ON COLUMN "check_items"."assignee_id" IS 'Member responsible for this item. Null is the normal case; it exists so a checklist can act as a lightweight split of work without creating five cards.';

CREATE INDEX "idx_check_items_order"
ON "check_items" ("checklist_id", "position");
CREATE INDEX "idx_check_items_assignee_due"
ON "check_items" ("assignee_id", "due_at");

CREATE TABLE IF NOT EXISTS "card_members" (
	-- Card involved. Half of the composite primary key.
	"card_id" BIGINT,
	-- Person attached. The other half of the key.
	"user_id" BIGINT,
	-- member | watcher. A member is shown as an avatar on the card face and implies responsibility; a watcher only receives notifications. One table because the two overlap almost entirely and a person is never both.
	"relation" VARCHAR(12) NOT NULL DEFAULT 'member',
	-- When they were attached or subscribed.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("card_id", "user_id")
);

COMMENT ON TABLE "card_members" IS 'Who is on a card and who is merely following it. Collapsing members and watchers into one table with a relation column keeps the notification fan-out a single query instead of a union of two.';
COMMENT ON COLUMN "card_members"."card_id" IS 'Card involved. Half of the composite primary key.';
COMMENT ON COLUMN "card_members"."user_id" IS 'Person attached. The other half of the key.';
COMMENT ON COLUMN "card_members"."relation" IS 'member | watcher. A member is shown as an avatar on the card face and implies responsibility; a watcher only receives notifications. One table because the two overlap almost entirely and a person is never both.';
COMMENT ON COLUMN "card_members"."added_at" IS 'When they were attached or subscribed.';

CREATE INDEX "idx_card_members_user"
ON "card_members" ("user_id", "relation");

CREATE TABLE IF NOT EXISTS "attachments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Card the file or link belongs to.
	"card_id" BIGINT NOT NULL,
	-- Uploader.
	"uploaded_by_id" BIGINT,
	-- file | link. A pasted URL is an attachment too, and giving it the same row shape means previews, covers and the activity feed handle both identically.
	"kind" VARCHAR(12) NOT NULL DEFAULT 'file',
	-- Object storage key for an uploaded file. Null for a link attachment; the database stores the pointer, never the bytes.
	"storage_key" VARCHAR(500),
	-- External URL for a link attachment, or the resolved download URL for a file.
	"url" VARCHAR(1000),
	-- Original filename shown in the UI.
	"filename" VARCHAR(255),
	-- Content type, which decides whether the attachment can serve as a card cover.
	"mime_type" VARCHAR(100),
	-- File size for quota accounting. Null for links, which cost nothing.
	"byte_size" BIGINT,
	-- Upload or paste time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "attachments" IS 'Files and links on a card. Attached to the card rather than to a comment, so a file survives the comment that introduced it being deleted.';
COMMENT ON COLUMN "attachments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "attachments"."card_id" IS 'Card the file or link belongs to.';
COMMENT ON COLUMN "attachments"."uploaded_by_id" IS 'Uploader.';
COMMENT ON COLUMN "attachments"."kind" IS 'file | link. A pasted URL is an attachment too, and giving it the same row shape means previews, covers and the activity feed handle both identically.';
COMMENT ON COLUMN "attachments"."storage_key" IS 'Object storage key for an uploaded file. Null for a link attachment; the database stores the pointer, never the bytes.';
COMMENT ON COLUMN "attachments"."url" IS 'External URL for a link attachment, or the resolved download URL for a file.';
COMMENT ON COLUMN "attachments"."filename" IS 'Original filename shown in the UI.';
COMMENT ON COLUMN "attachments"."mime_type" IS 'Content type, which decides whether the attachment can serve as a card cover.';
COMMENT ON COLUMN "attachments"."byte_size" IS 'File size for quota accounting. Null for links, which cost nothing.';
COMMENT ON COLUMN "attachments"."created_at" IS 'Upload or paste time.';

CREATE INDEX "idx_attachments_card_time"
ON "attachments" ("card_id", "created_at");

CREATE TABLE IF NOT EXISTS "board_power_ups" (
	-- Board the integration is enabled on. Half of the composite primary key.
	"board_id" BIGINT,
	-- Identifier of the integration such as calendar or github. The other half of the key, so enabling twice is impossible.
	"power_up_key" VARCHAR(80),
	-- Per-board configuration owned by the integration: a linked repository, a calendar feed token. Opaque to this schema by design, because the core product must not need a migration when an integration adds a field.
	"settings" JSONB,
	-- Who turned it on.
	"enabled_by_id" BIGINT,
	-- When it was enabled.
	"enabled_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("board_id", "power_up_key")
);

COMMENT ON TABLE "board_power_ups" IS 'Per-board integrations. Keeping their configuration as an opaque JSON blob is what lets third-party power-ups ship independently of the core schema.';
COMMENT ON COLUMN "board_power_ups"."board_id" IS 'Board the integration is enabled on. Half of the composite primary key.';
COMMENT ON COLUMN "board_power_ups"."power_up_key" IS 'Identifier of the integration such as calendar or github. The other half of the key, so enabling twice is impossible.';
COMMENT ON COLUMN "board_power_ups"."settings" IS 'Per-board configuration owned by the integration: a linked repository, a calendar feed token. Opaque to this schema by design, because the core product must not need a migration when an integration adds a field.';
COMMENT ON COLUMN "board_power_ups"."enabled_by_id" IS 'Who turned it on.';
COMMENT ON COLUMN "board_power_ups"."enabled_at" IS 'When it was enabled.';

CREATE TABLE IF NOT EXISTS "card_activity" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Board the event happened on, denormalised so the board feed is one index scan.
	"board_id" BIGINT NOT NULL,
	-- Card involved. Null for board-level events such as a list being renamed.
	"card_id" BIGINT,
	-- Who acted. Null for events produced by an automation rule or a power-up.
	"actor_id" BIGINT,
	-- card_created | card_moved | card_archived | comment_added | member_added | label_added | due_set | checklist_item_checked | list_created.
	"action" VARCHAR(40) NOT NULL,
	-- Event payload: the source and destination list for a move, the text for a comment, the label id. JSON because every action carries a different shape and none of them are queried on.
	"data" JSONB,
	-- When it happened.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "card_activity" IS 'Append-only feed, doubling as the comment thread and the audit log. One stream means the card back explains itself in order: moved here, commented on, due date set, archived.';
COMMENT ON COLUMN "card_activity"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "card_activity"."board_id" IS 'Board the event happened on, denormalised so the board feed is one index scan.';
COMMENT ON COLUMN "card_activity"."card_id" IS 'Card involved. Null for board-level events such as a list being renamed.';
COMMENT ON COLUMN "card_activity"."actor_id" IS 'Who acted. Null for events produced by an automation rule or a power-up.';
COMMENT ON COLUMN "card_activity"."action" IS 'card_created | card_moved | card_archived | comment_added | member_added | label_added | due_set | checklist_item_checked | list_created.';
COMMENT ON COLUMN "card_activity"."data" IS 'Event payload: the source and destination list for a move, the text for a comment, the label id. JSON because every action carries a different shape and none of them are queried on.';
COMMENT ON COLUMN "card_activity"."created_at" IS 'When it happened.';

CREATE INDEX "idx_card_activity_card_time"
ON "card_activity" ("card_id", "created_at");
CREATE INDEX "idx_card_activity_board_time"
ON "card_activity" ("board_id", "created_at");

ALTER TABLE "boards"
ADD FOREIGN KEY("owner_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "boards"
ADD FOREIGN KEY("template_source_board_id") REFERENCES "boards"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "board_members"
ADD FOREIGN KEY("board_id") REFERENCES "boards"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "board_members"
ADD FOREIGN KEY("user_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "lists"
ADD FOREIGN KEY("board_id") REFERENCES "boards"("id")
